          <div>
            {eyebrow && <p className="eyebrow mb-1">{eyebrow}</p>}
            <h2 className="font-display text-lg font-semibold tracking-[-0.02em] text-mist-50">{title}</h2>
            {subtitle && <p className="mt-1 text-[12px] text-mist-400">{subtitle}</p>}
